#!/bin/sh
# A channel transfer carries its own status in the tail of its
# half-interval, so the program reads it right after the transfer.
# Read status: end bit (1), errno (8), size (nfield bits), low bit
# first. Program: (32,0x2000,DATA) input 8 bits, (24,0x2100,0x2008)
# copy the 24 status bits, (47,DATA,0x2100) output them. DATA is the
# position after the space. At -s 65520 the read status is
# 1+8+15 = 24 bits and the write status is 8+15 = 23 bits.
set -e
cd "$(dirname "$0")/.."
if [ ! -x ./space ]; then
  echo "no ./space, run make first"
  exit 1
fi
